  it('wraps a thrown string, object, or undefined in an Error carrying cause while rethrowing the original', async () => {
    const rejectionOf = (call: Promise<unknown>): Promise<unknown> =>
      call.then(
        () => Symbol('resolved'),
        (thrown: unknown) => thrown
      );
    const cases = [
      {reason: 'string boom', expectedMessage: 'string boom'},
      {reason: {code: 503, detail: 'upstream down'}, expectedMessage: '{"code":503,"detail":"upstream down"}'},
      {reason: undefined, expectedMessage: 'undefined'},
    ];
    const results = [];

    for (const {reason} of cases) {
      const seen: Error[] = [];
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => {
          seen.push(error);
        },
      };
      const orchestrator = createChatOrchestrator(createErrorProvider(reason), promptBuilder, undefined, {hooks});
      const thrown = await rejectionOf(orchestrator.processMessage(createSession('hello')));
      const [recorded] = seen;

      results.push({
        callCount: seen.length,
        isError: recorded instanceof Error,
        message: recorded?.message,
        hasCause: recorded instanceof Error && 'cause' in recorded,
        causeMatches: recorded instanceof Error && recorded.cause === reason,
        rethrownUnchanged: thrown === reason,
      });
    }

    expect(results).toEqual(
      cases.map(({expectedMessage}) => ({
        callCount: 1,
        isError: true,
        message: expectedMessage,
        hasCause: true,
        causeMatches: true,
        rethrownUnchanged: true,
      }))
    );
  });
});

